import{_ as a,o as t,c as n,a0 as i}from"./chunks/framework.BxCN1dRw.js";const p=JSON.parse('{"title":"Documentation","description":"","frontmatter":{"docLocale":"en","counterpart":"/docs/"},"headers":[],"relativePath":"en/docs/index.md","filePath":"en/docs/index.md"}'),r={name:"en/docs/index.md"};function o(s,e,d,c,h,l){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h1><p>This is the unified entry to the online tutorials and the generated references. Everything shares one source with the repository: tutorial steps can be followed as-is, the <a href="./../reference/api">API contract</a> and the <a href="./../reference/config">configuration reference</a> are generated from the implementation, and each page&#39;s footer marks the repository commit the page was verified against.</p><ul><li>Start with the <a href="./../getting-started/quickstart">quick start</a> to run the template from a real request.</li><li>The <a href="./../tutorials/first-request">tutorials</a> walk through registration, sessions, documents, attachments, exports, members, audit and more, one real path at a time.</li><li>The <a href="./../reference/api">generated references</a> list the current API operationIds and configuration defaults, always matching the sources.</li><li>When you are ready to publish your own site, read <a href="./../getting-started/publish-docs">publish the documentation site</a>.</li></ul><h2 id="languages-and-scope" tabindex="-1">Languages and scope <a class="header-anchor" href="#languages-and-scope" aria-label="Permalink to &quot;Languages and scope&quot;">​</a></h2><p>The site ships in Simplified Chinese and English, switched from the language menu in the navigation bar; chapters correspond one to one. Chapters that have no translation yet do not appear in the English navigation and never pretend an English page exists. Search covers every published documentation page and generated reference on this site, not in-application data. Links decide the reading language; a shared link is never redirected by device language.</p><p>English coverage note: the quick start, this entry, the publishing guide and both generated references are fully available in English. The remaining tutorial chapters are registered migration items in <code>docs/site.json</code> and arrive with the implementation tickets that rework their features.</p><h2 id="maintaining-bilingual-chapters" tabindex="-1">Maintaining bilingual chapters <a class="header-anchor" href="#maintaining-bilingual-chapters" aria-label="Permalink to &quot;Maintaining bilingual chapters&quot;">​</a></h2><p>New pages must be delivered as a pair: place a same-named <code>.en.md</code> file next to the Chinese source and register one stable <code>id</code>, both titles and both group labels in <code>docs/site.json</code>. The publish checks validate chapter pairing, links and generated references; see <a href="./../getting-started/publish-docs">publish the documentation site</a> for the full steps.</p><hr><p>Source version：<code>4f971ed1cc0b</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/4f971ed1cc0b668fe275ee20981a83fc7d03ec9e/docs/getting-started/documentation.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>',10)])])}const g=a(r,[["render",o]]);export{p as __pageData,g as default};
